// Decide the conversation phase from the saved enquiry row.
// script = fixed questions still outstanding (answered without AI)
// chat   = questions done, conversational agent takes over
const body = $('chat1').first().json.body;
const row = items[0].json || {};

const KEYS = ['q1_business_overview', 'q2_daily_workflow', 'q3_bottlenecks', 'q4_systems_tools', 'q5_desired_outcomes'];
const filledCount = KEYS.filter((k) => row[k] && String(row[k]).trim()).length;

const mode = row.status === 'chat' || row.status === 'finished' || filledCount >= 5 ? 'chat' : 'script';

const context = KEYS
  .map((k, i) => (row[k] && String(row[k]).trim() ? `Q${i + 1} — ${String(row[k]).trim()}` : ''))
  .filter(Boolean)
  .join('\n');

return [{ json: { mode, filledCount, hasRow: Boolean(row.conversation_id), context: context || 'none recorded yet', row, body } }];

// Programmatic question flow — no AI. The first message of a conversation
// only gets the greeting + Question 1 (nothing is stored until it is
// actually answered). Every turn is appended to the transcript buffer.
const route = $('route').first().json;
const body = route.body;
const msg = String(body.message || '').trim();

const QUESTIONS = [
  ['q1_business_overview', "Quick one, 1 of 5 — could you tell me a bit about your role? Are you a practice nurse, and what kind of clinic do you work in?"],
  ['q2_daily_workflow', "2 of 5 — what does a typical shift look like for you? Which tasks take up more time than you'd like?"],
  ['q3_bottlenecks', "3 of 5 — where are the biggest frustrations in your day? For example care plans, recalls, stock, or documentation."],
  ['q4_systems_tools', "4 of 5 — which systems do you use day to day? For example Best Practice or another practice management system, HotDoc, spreadsheets, or paper lists."],
  ['q5_desired_outcomes', "Last one — if those tasks were handled, what would you want your shifts to look like instead?"],
];

const firstName = String(body.user_name || '').split(' ')[0];
let answerKey, answerValue, newStatus, reply;

if (!route.hasRow) {
  // First ever message: greet, ask Question 1, store nothing.
  answerKey = '(none)';
  answerValue = '';
  newStatus = 'new';
  reply = `Thanks${firstName ? ', ' + firstName : ''}! I'll come to that in a sec — first, ${QUESTIONS.length} quick questions so I can point you to the right tools (type "skip" any time you'd rather not answer).\n\n` + QUESTIONS[0][1];
} else {
  const idx = Math.min(route.filledCount, QUESTIONS.length - 1);
  answerKey = QUESTIONS[idx][0];
  answerValue = msg.toLowerCase() === 'skip' ? '(skipped)' : msg;
  newStatus = route.filledCount >= QUESTIONS.length - 1 ? 'chat' : 'script';
  reply = route.filledCount >= QUESTIONS.length - 1
    ? "You beauty — that's everything I need! Now, what would you like to know? I can tell you about NursePod, Docsert AI, cIQventory, PIPQI or the free calculators — or anything else on your mind."
    : QUESTIONS[idx + 1][1];
}

// Transcript buffer (workflow static data, pruned after 7 days).
const sd = $getWorkflowStaticData('global');
sd.transcripts = sd.transcripts || {};
const cid = body.conversation_id;
const stamp = new Date(body.timestamp || Date.now()).toLocaleString('en-AU', {
  timeZone: 'Australia/Sydney', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit',
});
const prev = (sd.transcripts[cid] && sd.transcripts[cid].text) || '';
sd.transcripts[cid] = {
  text: prev + `[${stamp}] You: ${msg}\n[${stamp}] ClinicIQ: ${reply}\n\n`,
  ts: Date.now(),
};
for (const k of Object.keys(sd.transcripts)) {
  if (Date.now() - (sd.transcripts[k].ts || 0) > 7 * 86400000) delete sd.transcripts[k];
}

return [{ json: { answerKey, answerValue, newStatus, reply, route } }];

// Same response shape the AI branch produces, so the widget can't tell
// the scripted phase from the conversational one.
const t = $('build script turn').first().json;
const body = t.route.body;
const KEYS = ['q1_business_overview', 'q2_daily_workflow', 'q3_bottlenecks', 'q4_systems_tools', 'q5_desired_outcomes'];

const answers = {};
KEYS.forEach((k, i) => {
  answers['q' + (i + 1)] = t.answerKey === k ? t.answerValue : (t.route.row[k] || '');
});

return [{ json: { output: {
  output: t.reply,
  status: 'in_progress',
  answers,
  metadata: {
    user_name: body.user_name || '',
    user_email: body.user_email || '',
    user_id: body.user_id || '',
    conversation_id: body.conversation_id || '',
    source: body.source || 'ClinicIQ Solutions Chat',
    timestamp: body.timestamp || '',
  },
} } }];

// The agent replies in plain text (no JSON parser — those fail the node on
// schema drift). Wrap its text for the widget; [END] marks a wrap-up turn.
// Every chat turn is appended to the transcript buffer.
const raw = items[0].json.output ?? items[0].json.text ?? '';
const body = $('chat1').first().json.body;
const meta = {
  user_name: body.user_name,
  user_email: body.user_email,
  user_id: body.user_id,
  conversation_id: body.conversation_id,
  source: body.source || 'ClinicIQ Solutions Chat',
  timestamp: body.timestamp,
};
let message = (typeof raw === 'string' ? raw : JSON.stringify(raw)).trim();
let status = 'in_progress';
if (/\[END\]\s*$/i.test(message)) {
  status = 'finished';
  message = message.replace(/\[END\]\s*$/i, '').trim();
}
if (!message) message = "I'm here — ask me anything about the ClinicIQ tools!";

const sd = $getWorkflowStaticData('global');
sd.transcripts = sd.transcripts || {};
const cid = body.conversation_id;
const stamp = new Date(body.timestamp || Date.now()).toLocaleString('en-AU', {
  timeZone: 'Australia/Sydney', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit',
});
const prev = (sd.transcripts[cid] && sd.transcripts[cid].text) || '';
sd.transcripts[cid] = {
  text: prev + `[${stamp}] You: ${String(body.message || '').trim()}\n[${stamp}] ClinicIQ: ${message}\n\n`,
  ts: Date.now(),
};

return [{ json: { output: { output: message, status, answers: {}, metadata: meta } } }];

// Build the enquiry notification email from the enquiry row + the full
// conversation transcript (accumulated in workflow static data).
const body = $('chat1').first().json.body;
const enquiries = [items[0].json.payload ?? items[0].json.data ?? items[0].json].flat();
if (!enquiries.length) throw new Error('No enquiry records found in payload.');
const latest = enquiries.reduce((a, b) => {
  if (!a) return b;
  const da = new Date(a.createdAt || 0), db = new Date(b.createdAt || 0);
  if (db > da) return b;
  if (db.getTime() === da.getTime()) return (b.id || 0) > (a.id || 0) ? b : a;
  return a;
}, null);

const {
  user_name, user_email, source,
  q1_business_overview, q2_daily_workflow, q3_bottlenecks, q4_systems_tools, q5_desired_outcomes,
  createdAt,
} = latest;

const sd = $getWorkflowStaticData('global');
const cid = body.conversation_id;
const transcript = ((sd.transcripts || {})[cid] || {}).text
  || 'No transcript recorded for this conversation.';

const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const reportRecipientName = 'John Saenz';
let createdDateDisplay = '';
try {
  createdDateDisplay = new Date(createdAt).toLocaleString('en-AU', {
    timeZone: 'Australia/Sydney', year: 'numeric', month: 'short', day: '2-digit', hour: '2-digit', minute: '2-digit',
  });
} catch (e) { createdDateDisplay = createdAt || ''; }

const subject = `New web enquiry from ${user_name || 'prospect'} via ${source || 'website chat'}`;

const html = `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>${subject}</title>
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <style>
    body { margin: 0; padding: 0; background-color: #f3f4f6; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif; color: #111827; }
    .wrapper { width: 100%; padding: 24px 12px; box-sizing: border-box; }
    .container { max-width: 720px; margin: 0 auto; background-color: #ffffff; border-radius: 12px; box-shadow: 0 10px 30px rgba(15, 23, 42, 0.12); overflow: hidden; border: 1px solid #e5e7eb; }
    .header { background: linear-gradient(135deg, #2563eb, #0ea5e9); color: #ffffff; padding: 24px 28px; }
    .header h1 { margin: 0; font-size: 22px; font-weight: 600; letter-spacing: 0.02em; }
    .header p { margin: 8px 0 0; font-size: 14px; opacity: 0.9; }
    .content { padding: 24px 28px 28px; }
    .greeting { font-size: 15px; margin-bottom: 16px; }
    .meta { font-size: 13px; color: #6b7280; margin-bottom: 20px; }
    .meta strong { color: #374151; }
    .section { margin-bottom: 18px; padding: 14px 16px; border-radius: 10px; background-color: #f9fafb; border: 1px solid #e5e7eb; }
    .section h2 { margin: 0 0 8px; font-size: 14px; font-weight: 600; color: #111827; text-transform: uppercase; letter-spacing: 0.04em; }
    .transcript { margin: 0; font-size: 13px; line-height: 1.7; color: #374151; white-space: pre-wrap; word-wrap: break-word; font-family: inherit; }
    .pill-row { margin-top: 10px; font-size: 12px; color: #6b7280; }
    .pill { display: inline-block; margin-right: 6px; margin-top: 4px; padding: 4px 10px; border-radius: 999px; background-color: #e0f0ff; color: #1d4ed8; font-weight: 500; }
    .footer { border-top: 1px solid #e5e7eb; padding-top: 16px; margin-top: 8px; font-size: 12px; color: #6b7280; }
    .footer p { margin: 4px 0; }
    .footer a { color: #2563eb; text-decoration: none; }
  </style>
</head>
<body>
  <div class="wrapper">
    <div class="container">
      <div class="header">
        <h1>New Web Enquiry – ClinicIQ Solutions</h1>
        <p>Full conversation transcript captured from the website chat.</p>
      </div>
      <div class="content">
        <p class="greeting">Hi ${reportRecipientName},</p>
        <p class="greeting">
          A new enquiry has been received via <strong>${source || 'ClinicIQ Solutions Chat'}</strong>.
          The full transcript is below — it usually carries more context than the quick answers alone.
        </p>

        <div class="meta">
          <p><strong>Lead name:</strong> ${esc(user_name) || 'N/A'}</p>
          <p><strong>Email:</strong> <a href="mailto:${esc(user_email)}" style="color:#2563eb;text-decoration:none;">${esc(user_email)}</a></p>
          ${createdDateDisplay ? `<p><strong>Enquiry time:</strong> ${createdDateDisplay}</p>` : ''}
          <p><strong>Conversation ID:</strong> ${esc(latest.conversation_id) || 'N/A'}</p>
        </div>

        <div class="section">
          <h2>Conversation transcript</h2>
          <p class="transcript">${esc(transcript)}</p>
        </div>

        <div class="section">
          <h2>Quick answers at a glance</h2>
          <div class="pill-row"><span class="pill">${esc(q1_business_overview) || 'Not provided.'}</span></div>
          <div class="pill-row"><span class="pill">${esc(q2_daily_workflow) || 'Not provided.'}</span></div>
          <div class="pill-row"><span class="pill">${esc(q3_bottlenecks) || 'Not provided.'}</span></div>
          <div class="pill-row"><span class="pill">${esc(q4_systems_tools) || 'Not provided.'}</span></div>
          <div class="pill-row"><span class="pill">${esc(q5_desired_outcomes) || 'Not provided.'}</span></div>
        </div>

        <div class="footer">
          <p>
            Suggested next step: reply to
            <a href="mailto:${esc(user_email)}">${esc(user_email)}</a>
            to schedule an introductory call and explore how ClinicIQ's AI overlays can take admin off their shifts.
          </p>
          <p>This email was generated automatically from the ClinicIQ Solutions chat transcript.</p>
        </div>
      </div>
    </div>
  </div>
</body>
</html>
`;

return [{ json: { to: `${reportRecipientName} <${user_email}>`, subject, html, enquiry: latest } }];

