=<!DOCTYPE html>
<html lang="en-AU">
<head>
  <meta charset="UTF-8" />
  <title>Thank You for Your Enquiry</title>
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <style>
    body {
      margin: 0;
      padding: 0;
      background-color: #f4f4f4;
      font-family: Arial, Helvetica, sans-serif;
    }
    table {
      border-collapse: collapse;
    }
    .wrapper {
      width: 100%;
      background-color: #f4f4f4;
      padding: 20px 0;
    }
    .container {
      max-width: 600px;
      margin: 0 auto;
      background-color: #ffffff;
      border-radius: 6px;
      overflow: hidden;
      border: 1px solid #e0e0e0;
    }
    .logo-wrapper {
      padding: 20px 0 10px 0;
      text-align: center;
      background-color: #ffffff;
    }
    .header {
      background-color: #0a4c7a;
      padding: 18px 24px;
      color: #ffffff;
    }
    .header h1 {
      margin: 0;
      font-size: 20px;
      font-weight: 600;
    }
    .body {
      padding: 20px 24px 24px 24px;
      color: #333333;
      font-size: 14px;
      line-height: 1.6;
    }
    .body h2 {
      font-size: 16px;
      margin: 0 0 8px 0;
      color: #0a4c7a;
    }
    .qa-block {
      margin: 16px 0;
      padding: 12px 14px;
      background-color: #f9fafb;
      border-radius: 4px;
      border: 1px solid #e5e7eb;
    }
    .question {
      font-weight: bold;
      margin-bottom: 4px;
      color: #111827;
    }
    .answer {
      margin: 0;
      color: #374151;
    }
    .meta {
      font-size: 12px;
      color: #6b7280;
      margin-top: 8px;
    }
    .footer {
      padding: 14px 24px 18px 24px;
      font-size: 12px;
      color: #6b7280;
      text-align: center;
    }
    .footer a {
      color: #0a4c7a;
      text-decoration: none;
    }
  </style>
</head>
<body>
  <table class="wrapper" width="100%" cellpadding="0" cellspacing="0" role="presentation">
    <tr>
      <td align="center">
        <table class="container" width="100%" cellpadding="0" cellspacing="0" role="presentation">


          <!-- Header -->
          <tr>
            <td class="header">
              <h1>Thank you for your enquiry</h1>
            </td>
          </tr>

          <!-- Logo -->
          <tr>
            <td class="logo-wrapper" align="center">
              <img src="https://downloads.cliniciq.com.au/icons/cliniciq-logo.png" alt="ClinicIQ Logo" width="140" style="display:block; margin:auto; max-width:140px;">
            </td>
          </tr>

          <!-- Body -->
          <tr>
            <td class="body">
              <p>Hi {{ $('chat1').item.json.body.user_name }},</p>

              <p>
                Thank you for taking the time to share a bit about your role and your shift with ClinicIQ Solutions.
                We’ve received your enquiry and the information you provided, and we’ll review everything carefully.
              </p>

              <p>
                John — Registered Nurse and founder — will be in touch shortly with suggestions, including tools you can start using free today, no practice sign-off needed.
              </p>

              <p>Kind regards,<br />
                John Saenz — Registered Nurse & Founder
              </p>
            </td>
          </tr>

          <!-- Footer -->
          <tr>
            <td class="footer">
              <p>
                ClinicIQ Solutions<br />
                <a href="https://cliniciq.com.au" target="_blank" rel="noopener noreferrer">cliniciq.com.au</a>
              </p>
            </td>
          </tr>

        </table>
      </td>
    </tr>
  </table>
</body>
</html>
